function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.globe}"/></svg>`}
function icons(){document.querySelectorAll('[data-icon]').forEach(e=>{e.innerHTML=icon(e.dataset.icon)})}
const people=[{id:'emma',name:'Emma Taylor',initials:'ET',role:'Software Developer',field:'Technology',location:'London, UK',skills:['JavaScript','Product','Web3'],intent:'Open to projects',bio:'Building thoughtful digital products. Interested in useful tools, strong teams and ideas that solve real problems.',color:'purple'}, {id:'daniel',name:'Daniel Morgan',initials:'DM',role:'Founder & Investor',field:'Business',location:'Manchester, UK',skills:['Strategy','Investing','Startups'],intent:'Meeting founders',bio:'Connecting with founders building their first products. Always happy to exchange ideas about sustainable businesses.',color:'gold'}, {id:'sarah',name:'Sarah Khan',initials:'SK',role:'Marketing Specialist',field:'Marketing',location:'Birmingham, UK',skills:['Branding','Growth','Content'],intent:'Available for work',bio:'Helping independent businesses find their voice. Looking for ambitious teams and creative collaborations.',color:'teal'}, {id:'aisha',name:'Aisha Rahman',initials:'AR',role:'Technical Recruiter',field:'Recruitment',location:'London, UK',skills:['Hiring','Engineering','Talent'],intent:'Hiring developers',bio:'Matching thoughtful people with teams where they can do their best work.',color:'purple'},{id:'alex',name:'Alex Turner',initials:'AT',role:'Independent Insurance Broker',field:'Finance',location:'Leeds, UK',skills:['Insurance','Small business','Risk'],intent:'Open to connections',bio:'Interested in meeting business owners and sharing practical ideas about protecting a growing business.',color:'gold'},{id:'james',name:'James Chen',initials:'JC',role:'Product Designer',field:'Design',location:'Bristol, UK',skills:['UX','Design systems','Research'],intent:'Looking for collaborators',bio:'Designing clear, accessible products. Looking to meet developers and founders who care about the details.',color:'teal'}];
