const events=[{id:'founders',title:'Founder introductions',topic:'Meet your next collaborator',day:'08',month:'OCT',time:'18:00 · Online',host:'Founders & Builders',icon:'people'},{id:'product',title:'From idea to first product',topic:'A practical conversation for builders',day:'12',month:'OCT',time:'19:00 · Online',host:'Developers & Designers',icon:'code'},{id:'pitch',title:'Open pitch evening',topic:'Share an idea. Find a fresh perspective.',day:'15',month:'OCT',time:'18:30 · Ideas Stage',host:'Founders & Builders',icon:'bolt'}];
