const defaultPosts=[{id:'p1',person:'emma',time:'24 min',text:'Some of the best projects start with a simple conversation.\n\nI’m putting together a small team for a new web project. Looking to connect with a product designer and someone who enjoys turning early ideas into something useful.',tags:['Collaboration','Product design'],likes:24,card:'Looking for a creative collaborator',cardSub:'Product design · Remote · Project collaboration'},{id:'p2',person:'daniel',time:'1 hr',text:'What’s the one thing you wish you knew before starting your first business?\n\nFor me: talk to the people you want to help before building the solution. Interested to hear your experiences.',tags:['Founders','Discussion'],likes:38},{id:'p3',person:'sarah',time:'2 hr',text:'A good network isn’t just a list of names. It’s people you can learn from, work with and support.\n\nI’m opening up a few conversations with small business owners this week. What are you working on?',tags:['Networking','Small business'],likes:19}];
let state={profile:{id:'me',name:'Krypton',initials:'K',role:'Founder · Building connections',location:'London, UK',field:'Business',skills:['Business','Technology','Networking'],intent:'Open to ideas',bio:'Meeting people, sharing ideas and finding the next opportunity to build something together.',color:''},posts:[],following:[],joined:[],saved:[],liked:[],rsvp:[],messages:{},comments:{}};
try{const saved=JSON.parse(sessionStorage.getItem('virtlink-preview-v1'));if(saved&&saved.profile&&Array.isArray(saved.posts))state={...state,...saved}}catch{}
let accountConnected=false,accountId=null,memberPosts=[],memberFeedError='',memberLoaded=false,memberDraft='',memberPosting=false;
const pendingLikes=new Set();let commentsPostId=null,memberComments=[],commentDraft='',commentsError='',commentsLoading=false,commentSending=false;
const previewProfile=structuredClone(state.profile);
let feedTab='all',selectedThread='emma',activeZone='Global Hub',searchQuery='',networkFilter='All fields',jobFilter='All types',toastTimer;
function save(){try{sessionStorage.setItem('virtlink-preview-v1',JSON.stringify({...state,profile:accountConnected?previewProfile:state.profile}))}catch{toast('Your browser cannot save this preview session.')}}
function person(id){return id==='me'?state.profile:people.find(p=>p.id===id)||people[0]}
function avatar(p,large=false){if(p.avatar_data&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(p.avatar_data))return `<img class="avatar ${large?'large':''}" style="object-fit:cover" src="${esc(p.avatar_data)}" alt="">`;return `<span class="avatar ${esc(p.color||'')} ${large?'large':''}" aria-hidden="true">${esc(p.initials)}</span>`}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
function closeModal(){commentsPostId=null;$('#modal').close()}
const nav=[['feed','home','Home Feed'],['network','people','My Network'],['jobs','briefcase','Jobs & Opportunities'],['investors','briefcase','Investors'],['messages','message','Messages'],['communities','people','Communities'],['events','calendar','Events'],['marketplace','shop','Marketplace'],['world','globe','World']];
function mobile(route){if(accountConnected)return `<nav class="mobileNav" aria-label="Member navigation"><a href="#feed">${icon('home')}Feed</a><a href="#profile">${icon('user')}Profile</a><a href="accounts.html">${icon('shield')}Account</a></nav>`;return `<nav class="mobileNav" aria-label="Mobile navigation">${[['feed','home','Home'],['network','people','People'],['world','globe','World'],['messages','message','Messages'],['menu','plus','More']].map(([r,i,n])=>`<a href="#${r}" class="${r===route?'active':''}">${icon(i)}${n}</a>`).join('')}</nav>`}
function sidebar(route){if(accountConnected)return `<aside class="sidebar"><div class="sideTitle">MEMBER TEST AREA</div><nav><a class="sideLink" href="#feed">${icon('home')}Member feed</a><a class="sideLink" href="#profile">${icon('user')}My profile</a><a class="sideLink" href="accounts.html">${icon('shield')}Account settings</a></nav><footer><a href="#privacy">Privacy</a> · <a href="#terms">Terms</a></footer></aside>`;return `<aside class="sidebar"><nav aria-label="Explore VIRTLINK">${nav.map(([r,i,n])=>`<a class="sideLink ${route===r?'active':''}" href="#${r}">${icon(i)}${n}</a>`).join('')}</nav><div class="sideTitle">YOUR SPACE</div><a class="sideLink ${route==='profile'?'active':''}" href="#profile">${icon('user')}My Profile</a><a class="sideLink ${route==='saved'?'active':''}" href="#saved">${icon('bookmark')}Saved items</a><div class="sideWorld"><h3>${icon('globe')}Enter the World</h3><p>A new way to meet. Explore the Global Hub concept.</p><a class="button primary" href="#world">Explore World ${icon('arrow')}</a></div><footer><a href="#security">Trust & security</a> · <a href="#terms">Terms</a> · <a href="#privacy">Privacy</a> · <a href="#investor-policy">Investor policy</a> · <button class="textButton" data-action="about">About preview</button><br>VIRTLINK © 2026</footer></aside>`}
function followButton(p,mini=false){const on=state.following.includes(p.id);return `<button class="${mini?'miniButton':'ghost'}" data-action="follow" data-id="${p.id}" aria-label="${on?'Unfollow':'Follow'} ${esc(p.name)}">${mini?icon(on?'check':'plus'):on?'Following':'Follow'}</button>`}
function rail(){if(accountConnected)return `<aside class="rightRail stack"><section class="panel pad"><h3>Your member space</h3><p>Profile, posts, likes and comments are saved to your account.</p><p class="muted">Private messages, investor introductions and the member directory are not available yet.</p><a href="accounts.html" class="textButton">Account settings →</a></section></aside>`;return `<aside class="rightRail stack"><section class="panel pad"><div class="between"><h3>People to connect with</h3>${icon('people')}</div>${people.slice(0,3).map(p=>`<div class="row person"><a href="#profile/${p.id}">${avatar(p)}</a><a href="#profile/${p.id}" class="grow"><b>${esc(p.name)}</b><br><small>${esc(p.role)}</small></a>${followButton(p,true)}</div>`).join('')}<a href="#network" class="textButton" style="display:block;margin-top:14px">Explore your network →</a></section><section class="panel worldTeaser"><img src="world.jpg" alt="VIRTLINK Global Hub concept city"><div class="pad"><div class="eyebrow">ANOTHER WAY TO CONNECT</div><h3>Your network. A whole new world.</h3><p>Discover the spaces designed for ideas, people and opportunity.</p><a href="#world" class="button primary">Explore the World ${icon('arrow')}</a></div></section><section class="panel pad"><h3>Upcoming · sample events</h3>${events.slice(0,2).map(e=>`<a class="event" href="#events"><div class="date">${e.month}<b>${e.day}</b></div><div><h4>${e.title}</h4><p>${e.time}</p></div></a>`).join('')}</section><small>Sample profiles and opportunities are for demonstration.</small></aside>`}
function layout(route,content){return `<div class="layout">${sidebar(route)}<main id="main" class="stack">${content}</main>${rail()}</div>${mobile(route)}`}
function welcome(){return `<main id="main" class="welcome"><section class="welcomeHero"><img class="heroCity" src="world.jpg" alt="VIRTLINK futuristic Global Hub city concept"><div class="welcomeCopy"><div class="eyebrow">WELCOME TO VIRTLINK</div><h1>PEOPLE<br>IDEAS<br>OPPORTUNITIES<br><span>IN ONE PLACE.</span></h1><p>A new way to meet, connect and build the future. Your network, with a world of possibilities.</p><div class="row"><a class="button primary" href="#world">Enter World ${icon('globe')}</a><a class="button ghost" href="#feed">Explore Feed</a></div><small>Get to know the platform before you join.</small></div><div class="heroCaption"><span>GLOBAL HUB</span><small>World concept preview</small></div><div class="welcomeFeatures"><a href="#world">${icon('globe')}<h3>3D Networking</h3><p>Explore the World concept</p></a><a href="#network">${icon('people')}<h3>Find your people</h3><p>Connect through shared goals</p></a><a href="#jobs">${icon('briefcase')}<h3>Jobs & Opportunities</h3><p>Find work or the right talent</p></a><a href="#communities">${icon('people')}<h3>Communities</h3><p>Join your interests</p></a></div></section><section class="welcomeLower"><div><div class="eyebrow">YOUR NETWORK STARTS HERE</div><h2>Share an idea. Find a collaborator. Start a conversation.</h2><p>A familiar social platform, with an optional World when you want to explore something different.</p></div><button class="primary" data-action="signup">Join VIRTLINK ${icon('arrow')}</button></section>${policyLinks()}</main>`}
function postCard(post){const p=person(post.person),liked=state.liked.includes(post.id),saved=state.saved.includes(post.id);return `<article class="panel post"><div class="row"><a href="#profile/${p.id}">${avatar(p)}</a><div class="grow"><a href="#profile/${p.id}"><b>${esc(p.name)}</b></a><div><small>${esc(p.role)} · ${esc(post.time)}</small></div></div><button class="textButton" data-action="report" data-id="${esc(post.id)}" aria-label="Report post">···</button></div><p class="bodyText">${esc(post.text)}</p>${post.card?`<a href="#network" class="postCard" style="display:block"><div class="eyebrow">LET’S BUILD SOMETHING</div><h3>${esc(post.card)}</h3><small>${esc(post.cardSub)}</small></a>`:''}<div>${(post.tags||[]).map(t=>`<span class="chip blue">#${esc(t)}</span>`).join('')}</div><div class="postActions"><button class="${liked?'selected':''}" data-action="like" data-id="${esc(post.id)}">${icon('heart')}${post.likes+(liked?1:0)}</button><button data-action="comment" data-id="${esc(post.id)}">${icon('message')}Comment${state.comments[post.id]?.length?' · '+state.comments[post.id].length:''}</button><button data-action="share" data-id="${esc(post.id)}">${icon('share')}Share</button><button class="${saved?'selected':''}" data-action="save" data-id="${esc(post.id)}">${icon('bookmark')}${saved?'Saved':'Save'}</button></div></article>`}

function memberPostCard(post){return `<article class="panel post"><div class="row"><span class="avatar">${esc(post.author_name.slice(0,1).toUpperCase())}</span><div class="grow"><b>${esc(post.author_name)}</b><div><small>@${esc(post.author_username)} · ${esc(new Date(post.created_at).toLocaleString())}</small></div></div>${post.author_id===accountId?`<button class="textButton" data-action="deletepost" data-id="${esc(post.id)}">Delete</button>`:''}</div><p class="bodyText">${esc(post.body)}</p><div class="postActions"><button data-action="memberlike" data-id="${esc(post.id)}" aria-pressed="${Boolean(post.liked)}" ${pendingLikes.has(post.id)?'disabled':''}>${icon('heart')}${post.liked?'Unlike':'Like'} · ${Number(post.like_count||0)}</button><button data-action="membercomments" data-id="${esc(post.id)}">${icon('message')}Comments · ${Number(post.comment_count||0)}</button></div></article>`;}
function memberFeed(){return `<div class="sectionHead"><div class="eyebrow">YOUR NETWORK, IN MOTION</div><h1>Welcome back, ${esc(state.profile.name.split(' ')[0])}.</h1><p>Share ideas and opportunities with members.</p></div><section class="panel pad composer"><form id="memberPostForm"><div class="row">${avatar(state.profile)}<label class="grow"><span class="muted">Share with members</span><textarea name="post" placeholder="Share an idea or opportunity…" maxlength="2000" required aria-label="Write a member post">${esc(memberDraft)}</textarea></label></div><div class="between"><small>Your post, display name and username will be visible to signed-in members.</small><button class="primary" type="submit" ${memberPosting?'disabled':''}>${memberPosting?'Publishing…':'Publish post'}</button></div></form></section><div class="between"><h2>Member posts</h2><button data-action="refreshposts">Refresh</button></div><small>Latest 50 posts · refreshed when you open the site or press Refresh</small>${memberFeedError?`<div class="notice" role="alert">${esc(memberFeedError)}</div>`:''}<div class="stack">${memberPosts.map(memberPostCard).join('')||`<div class="panel empty">${memberLoaded?'No posts yet. Share the first idea.':'Loading member posts…'}</div>`}</div>`;}

function feed(){if(accountConnected)return memberFeed();let posts=[...state.posts,...defaultPosts];if(feedTab==='following')posts=posts.filter(p=>state.following.includes(p.person)||p.person==='me');return `<div class="sectionHead"><div class="eyebrow">YOUR NETWORK, IN MOTION</div><h1>Welcome back, ${esc(state.profile.name.split(' ')[0])}.</h1><p>New ideas. Useful conversations. Your next connection.</p></div><section class="panel pad composer"><form id="postForm"><div class="row">${avatar(state.profile)}<label class="grow"><span class="muted">Share with your network</span><textarea name="post" placeholder="An idea, an opportunity, or something you’re working on…" maxlength="2000" required aria-label="Write a post"></textarea></label></div><div class="between"><span class="muted" style="font-size:12px">${icon('globe')} Preview post · this session only</span><button class="primary" type="submit">Post ${icon('arrow')}</button></div></form></section><div><div class="tabs"><button class="tab ${feedTab==='all'?'active':''}" data-action="feedtab" data-id="all">For you</button><button class="tab ${feedTab==='following'?'active':''}" data-action="feedtab" data-id="following">Following</button><a class="tab" href="#jobs">Opportunities</a></div><div class="stack">${posts.map(postCard).join('')||'<div class="panel empty">Follow someone in your network to see their posts here.<br><a href="#network" class="textButton">Find people →</a></div>'}</div></div>`}
function personCard(p){return `<article class="panel pad personCard"><a href="#profile/${p.id}">${avatar(p)}<h3>${esc(p.name)}</h3></a><p>${esc(p.role||'Add a headline or profession')}</p><small>${icon('pin')} ${esc(p.location||'Add your city or country')}</small><div style="margin-top:10px">${p.skills.map(s=>`<span class="chip">${esc(s)}</span>`).join('')||'<p class="muted">Add your skills in Edit profile.</p>'}</div><div class="row">${followButton(p)}<button class="primary" data-action="message" data-id="${p.id}">Message</button></div></article>`}
function network(){return `<div class="sectionHead"><div class="eyebrow">PEOPLE MAKE THINGS POSSIBLE</div><h1>Find your people.</h1><p>Connect through skills, interests and what you’re looking for.</p></div><form class="filters" id="networkFilter"><input name="q" placeholder="Name, skill or profession" aria-label="Filter people" value="${esc(searchQuery)}"><select name="field" aria-label="Industry">${['All fields','Technology','Business','Marketing','Recruitment','Finance','Design'].map(x=>`<option ${x===networkFilter?'selected':''}>${x}</option>`).join('')}</select><button class="primary">Search</button></form><div class="peopleGrid">${people.filter(p=>(networkFilter==='All fields'||p.field===networkFilter)&&JSON.stringify(p).toLowerCase().includes(searchQuery.toLowerCase())).map(personCard).join('')||'<div class="panel empty">No people match. Try another skill or field.</div>'}</div>`}
function jobsPage(){const list=jobs.filter(j=>jobFilter==='All types'||jobFilter===j.type);return `<div class="sectionHead"><div class="eyebrow">MAKE YOUR NEXT MOVE</div><h1>Jobs & opportunities</h1><p>Find work, a project or the person who brings your idea to life.</p></div><div class="filters"><select id="jobType" aria-label="Opportunity type">${['All types','Full-time','Freelance','Contract','Co-founder'].map(x=>`<option ${jobFilter===x?'selected':''}>${x}</option>`).join('')}</select><button data-action="postopportunity">Post an opportunity</button></div><div class="stack">${list.map(j=>`<article class="panel job"><div class="row"><div class="companyMark">${j.company[0]}</div><div><small>${j.company}</small><h3>${j.title}</h3></div></div><p class="description">${j.description}</p><span class="chip">${j.location}</span><span class="chip">${j.type}</span><div class="between"><span>${j.skills}</span><button class="primary" data-action="job" data-id="${j.id}">View opportunity ${icon('arrow')}</button></div></article>`).join('')}</div>`}
function communities(){return `<div class="sectionHead"><div class="eyebrow">FIND WHERE YOU BELONG</div><h1>Communities</h1><p>Good conversations start with something in common.</p></div><div class="cardGrid">${groups.map(g=>`<article class="panel"><div class="categoryArt">${icon(g.icon)}</div><div class="pad"><small>${g.tag} · ${g.members} sample members</small><h3>${g.name}</h3><p>${g.description}</p><button class="${state.joined.includes(g.id)?'ghost':'primary'}" data-action="group" data-id="${g.id}">${state.joined.includes(g.id)?'Open community':'Explore community'}</button></div></article>`).join('')}</div>`}
function eventsPage(){return `<div class="sectionHead"><div class="eyebrow">BETTER CONVERSATIONS, TOGETHER</div><h1>Events & meetups</h1><p>Explore sample gatherings for your community.</p></div><div class="stack">${events.map(e=>`<article class="panel pad"><div class="row"><div class="date">${e.month}<b>${e.day}</b></div><div class="grow"><small>${e.host}</small><h3>${e.title}</h3></div>${icon(e.icon)}</div><p class="muted" style="margin:16px 0">${e.topic}</p><div class="between"><small>${e.time}</small><button class="${state.rsvp.includes(e.id)?'ghost':'primary'}" data-action="rsvp" data-id="${e.id}">${state.rsvp.includes(e.id)?'Saved to your events':'View event'}</button></div></article>`).join('')}</div>`}
function marketplace(){return `<div class="sectionHead"><div class="eyebrow">THE RIGHT EXPERTISE, CLOSER</div><h1>Marketplace</h1><p>Discover people and services to help your business move forward.</p></div><div class="cardGrid">${services.map(s=>{const p=person(s.person);return `<article class="panel pad"><div class="row">${avatar(p)}<div><b>${p.name}</b><br><small>${s.type}</small></div></div><h3 style="margin-top:20px">${s.name}</h3><p>${s.text}</p><button class="primary" data-action="message" data-id="${p.id}">Start a conversation</button></article>`}).join('')}</div>`}
function profile(id='me'){const p=person(id),mine=id==='me',ownPosts=memberPosts.filter(x=>x.author_id===accountId),useMember=mine&&accountConnected;return `<section class="panel"><div class="profileCover" ${useMember?'style="background:linear-gradient(115deg,#203958,#235083,#142740)"':''}></div><div class="profileHead"><div class="between">${avatar(p,true)}${mine?'<button data-action="editprofile">Edit profile</button>':followButton(p)}</div><h1>${esc(p.name)}</h1><p>${esc(p.role||'Add a headline or profession')}</p><small>${icon('pin')} ${esc(p.location||'Add your city or country')}</small><div style="margin-top:12px">${p.intent?`<span class="chip blue">${esc(p.intent)}</span>`:''}<span class="chip">${mine?(accountConnected?'Your account profile':'Preview profile'):'Sample profile'}</span></div>${useMember?'<p class="muted">Your saved profile · networking features are still being connected.</p>':`<div class="profileStats"><div><b>${mine?state.following.length:'—'}</b><span>Following</span></div><div><b>${mine?state.joined.length:'—'}</b><span>Communities</span></div><div><b>${useMember?ownPosts.length:[...state.posts,...defaultPosts].filter(x=>x.person===id).length}</b><span>Posts</span></div></div>`}${!mine?`<button class="primary" style="margin-top:20px" data-action="message" data-id="${p.id}">${icon('message')}Message</button>`:''}</div></section><section class="panel pad"><h2>About</h2><p class="muted" style="margin:12px 0 22px;white-space:pre-wrap">${esc(p.bio||'Tell people a little about yourself. Choose Edit profile to add your introduction.')}</p><h3>Skills & interests</h3><div style="margin-top:10px">${p.skills.map(s=>`<span class="chip">${esc(s)}</span>`).join('')||'<p class="muted">Add your skills in Edit profile.</p>'}</div></section><h2>Recent activity</h2>${(useMember?ownPosts.map(memberPostCard).join(''):[...state.posts,...defaultPosts].filter(x=>x.person===id).map(postCard).join(''))||'<div class="panel empty">No posts yet.</div>'}`}
function messages(){const p=person(selectedThread);return `<div class="sectionHead"><h1>Messages</h1><p>Your conversations, in one place.</p></div><div class="notice">Messaging demo only. Messages are saved in this browser session and are not sent to anyone. End-to-end encryption is not connected.</div><section class="panel inbox"><div class="threadList"><h3>Conversations</h3>${people.slice(0,5).map(p=>`<button class="threadButton ${selectedThread===p.id?'active':''}" data-action="thread" data-id="${p.id}">${avatar(p)}<div>${p.name.split(' ')[0]}<br><small>Sample conversation</small></div></button>`).join('')}</div><div class="chatColumn"><div class="chatHeader row">${avatar(p)}<div><a href="#profile/${p.id}"><b>${p.name}</b></a><br><small>${p.role}</small></div></div><div class="chatBody"><div class="muted" style="text-align:center;font-size:12px">Conversation preview · no live recipient</div>${(state.messages[p.id]||[]).map(t=>`<div class="bubble sent">${esc(t)}</div>`).join('')||'<div class="empty">Start with a hello.<br>Try writing a sample message below.</div>'}</div><form class="chatForm" id="messageForm"><input name="message" placeholder="Write a sample message…" aria-label="Write a sample message" required maxlength="2000"><button class="primary" aria-label="Save sample message">${icon('arrow')}</button></form></div></section>`}
const zones={'Global Hub':'The central meeting place. Discover people, explore districts and find a conversation that interests you.','Business District':'A space for founders, investors, brokers and professionals to meet and exchange ideas.','Jobs Hub':'Explore hiring sessions, freelance introductions and opportunities to work together.','Ideas Stage':'A place for pitches, open discussions and conversations about what comes next.','Community Spaces':'Rooms for people with shared interests, professions and goals.'};
function world(){return `<main id="main" class="worldPage"><div class="worldToolbar"><div><div class="eyebrow">VIRTLINK WORLD</div><h1>A place for real connections.</h1><p>Approved city concept · visual preview, not a live 3D environment</p></div><a href="#feed" class="button ghost">Back to feed</a></div><img class="worldImage" src="world.jpg" alt="Approved VIRTLINK World concept with a blue central globe, Business District, Jobs Hub, Ideas Stage and Community Spaces. People and controls shown inside this artwork are illustrative."><div class="worldBelow"><section class="panel pad"><h2>Explore the districts</h2><div class="worldZones">${Object.keys(zones).map(z=>`<button class="${z===activeZone?'active':''}" data-action="zone" data-id="${z}">${z}</button>`).join('')}</div><h3 style="margin-top:20px">${activeZone}</h3><p>${zones[activeZone]}</p><a href="#${activeZone==='Jobs Hub'?'jobs':activeZone==='Community Spaces'?'communities':'network'}" class="button primary">${activeZone==='Jobs Hub'?'Explore opportunities':activeZone==='Community Spaces'?'Find communities':'Meet the network'} ${icon('arrow')}</a></section><section class="panel pad"><div class="eyebrow">ONE PROFILE. MORE POSSIBILITIES.</div><h2>Stay connected, your way.</h2><p>Use the normal social platform any time. The World is a separate experience for live networking and events.</p><div class="row"><a class="button" href="#profile">${icon('user')}Your profile</a><a class="button" href="#events">${icon('calendar')}Events</a><a class="button" href="#messages">${icon('message')}Messages</a></div><p style="font-size:12px;margin-top:20px">Avatar movement, proximity voice and live presence are planned for the 3D build. The controls within the reference artwork are not interactive.</p></section></div></main>${mobile('world')}`}
function security(){return `<div class="sectionHead"><div class="eyebrow">TRUST & SECURITY</div><h1>Security before signup.</h1><p>Public registration is closed during this concept preview.</p></div><section class="panel pad"><h2>Protecting your information</h2><p class="muted" style="margin:12px 0">This preview does not collect passwords, identity documents or payment details. Use fictional details when testing profile editing.</p><p class="muted">Sample posts, follows and messages stay in this browser session. Do not enter private or sensitive information.</p><button style="margin-top:20px" data-action="reset">Clear my preview data</button></section><section class="panel pad"><h2>Required before public launch</h2><p class="muted" style="margin-top:12px">Email verification, server-checked bot protection, secure password storage, two-factor authentication, protected sessions, rate limits and abuse reporting.</p><p class="muted" style="margin-top:12px">Private messaging must use a reviewed end-to-end encryption implementation, including device verification and recovery. This preview does not implement encrypted messaging.</p></section>`}
function searchResults(){const q=searchQuery.toLowerCase();const matches=[['People',people.filter(p=>JSON.stringify(p).toLowerCase().includes(q)).map(p=>[p.name,p.role,'profile/'+p.id])],['Opportunities',jobs.filter(p=>JSON.stringify(p).toLowerCase().includes(q)).map(p=>[p.title,p.company,'jobs'])],['Communities',groups.filter(p=>JSON.stringify(p).toLowerCase().includes(q)).map(p=>[p.name,p.tag,'communities'])],['Investors',investorExamples.filter(p=>JSON.stringify(p).toLowerCase().includes(q)).map(p=>[p.name,p.type,'investors'])],['Services',services.filter(p=>JSON.stringify(p).toLowerCase().includes(q)).map(p=>[p.name,p.type,'marketplace'])]];return `<div class="sectionHead"><h1>Search results</h1><p>${q?'Results for “'+esc(searchQuery)+'”':'Enter a name, skill or topic in the search bar.'}</p></div>${q?matches.map(([title,rows])=>rows.length?`<section class="panel pad resultsGroup"><h2>${title}</h2>${rows.map(([name,detail,url])=>`<a href="#${url}"><div><b>${esc(name)}</b><br><small>${esc(detail)}</small></div>${icon('arrow')}</a>`).join('')}</section>`:'').join('')||'<div class="panel empty">No matches. Try “developer”, “insurance” or “founder”.</div>':''}`}
function render(){const parts=location.hash.slice(1).split('/'),route=parts[0]||'welcome';let content;if(route==='welcome')content=welcome();else if(route==='world')content=world();else {const pages={menu:()=>`<div class="sectionHead"><h1>Explore VIRTLINK</h1></div><nav class="panel pad mobileMenu" aria-label="All sections">${nav.map(([r,i,n])=>`<a class="sideLink" href="#${r}">${icon(i)}${n}</a>`).join('')}<a class="sideLink" href="#profile">${icon('user')}My profile</a><a class="sideLink" href="#terms">Terms & conditions</a><a class="sideLink" href="#privacy">Privacy</a><a class="sideLink" href="#investor-policy">Investor policy</a><a class="sideLink" href="#community-policy">Community policy</a><a class="sideLink" href="#security">Trust & security</a></nav>`,feed,network,investors:investorsPage,terms:()=>policyPage('terms'),privacy:()=>policyPage('privacy'),'investor-policy':()=>policyPage('investor'),'community-policy':()=>policyPage('community'),jobs:jobsPage,communities,events:eventsPage,marketplace,messages,security,search:searchResults,profile:()=>profile(parts[1]||'me'),saved:()=>`<div class="sectionHead"><h1>Saved items</h1><p>Ideas worth coming back to.</p></div>${[...state.posts,...defaultPosts].filter(p=>state.saved.includes(p.id)).map(postCard).join('')||'<div class="panel empty">Save posts from your feed to find them here.</div>'}`};content=layout(route,(pages[route]||feed)())}if(accountConnected){
 const allowed=['feed','profile','privacy','terms','security','community-policy','investor-policy'];
 if(route==='welcome')content=layout('feed',memberFeed());
 else if(!allowed.includes(route)||(route==='profile'&&parts[1]&&parts[1]!=='me'))content=layout(route,`<section class="panel pad"><h1>Not available in member testing</h1><p>This feature is not connected yet. Your real account is kept separate from the demonstration.</p><a class="button primary" href="#feed">Return to member feed</a></section>`);
}
 document.querySelector('.topnav').style.display=accountConnected?'none':'';
 document.querySelector('#searchForm').style.display=accountConnected?'none':'';
 document.querySelectorAll('.headerActions [href="#messages"],.headerActions [data-action="notifications"]').forEach(el=>el.style.display=accountConnected?'none':'');
 $('#app').innerHTML=content;document.querySelectorAll('.topnav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));document.querySelectorAll('.meAvatar').forEach(a=>a.textContent=state.profile.initials);document.title=`VIRTLINK · ${route==='welcome'?'People. Ideas. Opportunities.':route.charAt(0).toUpperCase()+route.slice(1)}`;icons()}
function toggle(key,id){state[key]=state[key].includes(id)?state[key].filter(x=>x!==id):[...state[key],id];save();render()}
function editProfile(){if(accountConnected){const p=state.profile;modal(`<h2>Edit profile</h2><form id="memberProfileForm"><label>Profile picture<input id="memberPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><img id="memberPhotoPreview" alt="Profile picture preview" style="width:80px;height:80px;object-fit:cover;border-radius:50%" ${p.avatar_data?`src="${esc(p.avatar_data)}"`:'hidden'}><p id="memberProfileStatus" role="status"></p>${[['username','Username',p.username||''],['display_name','Display name',p.name],['headline','Headline',p.role],['profession','Profession',p.field],['location','City / country',p.location],['skills','Skills',p.skills.join(', ')],['looking_for','Looking for',p.intent]].map(([key,label,value])=>`<label>${label}<input name="${key}" value="${esc(value||'')}" maxlength="${key==='username'?30:key==='display_name'?80:key==='skills'?400:key==='profession'?100:key==='location'?120:160}" ${['username','display_name'].includes(key)?'required':''} ${key==='username'?'pattern="[a-z][a-z0-9_]{2,29}"':''}></label>`).join('')}<label>About you<textarea name="bio" rows="4" maxlength="2000">${esc(p.bio)}</textarea></label><button class="primary">Save changes</button><button type="button" data-action="close">Cancel</button></form>`);return;}const p=state.profile;modal(`<h2>Your preview profile</h2><p>Try the layout with fictional details. This creates no account and stays in this session.</p><form id="profileForm"><div class="formGrid"><label>Display name<input name="name" value="${esc(p.name)}" required maxlength="50" autocomplete="off"></label><label>Location<input name="location" value="${esc(p.location)}" maxlength="80" autocomplete="off"></label></div><label>Professional headline<input name="role" value="${esc(p.role)}" required maxlength="100"></label><label>Skills · separate with commas<input name="skills" value="${esc(p.skills.join(', '))}" maxlength="160"></label><label>What are you looking for?<input name="intent" value="${esc(p.intent)}" maxlength="100"></label><label>About<textarea name="bio" rows="3" maxlength="600">${esc(p.bio)}</textarea></label><button class="primary">Save preview profile</button></form>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;switch(action){case'memberlike':{const post=memberPosts.find(p=>p.id===id);if(!post||pendingLikes.has(id))break;pendingLikes.add(id);render();window.dispatchEvent(new CustomEvent('virtlink-like',{detail:{postId:id,liked:!post.liked}}));break;}case'membercomments':commentsPostId=id;memberComments=[];commentDraft='';commentsError='';commentsLoading=true;commentSending=false;renderComments();window.dispatchEvent(new CustomEvent('virtlink-comments-load',{detail:id}));break;case'deletecomment':if(commentsPostId){b.disabled=true;window.dispatchEvent(new CustomEvent('virtlink-comment-delete',{detail:{id,postId:commentsPostId}}));}break;case'refreshposts':window.dispatchEvent(new Event('virtlink-feed-refresh'));break;case'deletepost':modal(`<h2>Delete this post?</h2><p>This removes it from the member feed.</p><button class="primary" data-action="confirmdeletepost" data-id="${esc(id)}">Delete post</button>`);break;case'confirmdeletepost':closeModal();window.dispatchEvent(new CustomEvent('virtlink-post-delete',{detail:id}));break;case'close':closeModal();break;case'about':modal('<h2>Explore the VIRTLINK concept</h2><p>Try the feed, profiles, follows, search, saved posts, community rooms, events and sample messages. Your changes last for this browser session.</p><p>Signed-in test accounts can publish saved posts to the member feed. Other people, jobs and events shown are examples. No private messages, applications or invitations are sent. The World uses the approved concept artwork.</p><p>Public signup and live messaging remain closed until verification, multi-factor authentication and end-to-end encryption are configured and tested.</p><a class="button primary" href="#security" data-action="close">View security details</a>');break;case'notifications':modal('<h2>You’re all caught up</h2><p>There are no live notifications in the concept preview. Your future connections, messages and event updates will appear here.</p>');break;case'signin':location.href='accounts.html';break;case'signout':window.dispatchEvent(new Event('virtlink-signout'));break;case'signup':location.href='accounts.html#register';break;case'editprofile':editProfile();break;case'follow':toggle('following',id);break;case'like':toggle('liked',id);break;case'save':toggle('saved',id);break;case'feedtab':feedTab=id;render();break;case'message':selectedThread=id;location.hash='messages';if(location.hash==='#messages')render();break;case'thread':selectedThread=id;render();break;case'zone':activeZone=id;render();break;case'comment':modal(`<h2>Comments</h2><p>Sample conversation · this session only.</p>${(state.comments[id]||[]).map(c=>`<div class="panel pad" style="margin:10px 0">${esc(c)}</div>`).join('')}<form id="commentForm" data-id="${esc(id)}"><label>Your comment<textarea name="comment" required maxlength="1000" rows="3"></textarea></label><button class="primary">Add sample comment</button></form>`);break;case'share':try{await navigator.clipboard.writeText(location.origin+location.pathname+'#feed');toast('Preview feed link copied.')}catch{modal(`<h2>Share the preview</h2><input aria-label="Preview link" readonly value="${esc(location.origin+location.pathname+'#feed')}">`)}break;case'report':modal('<h2>Report a concern</h2><p>This is a sample post. Live moderation will be connected before public posting opens.</p><form id="reportForm"><label>Reason<select name="reason"><option>Spam or misleading content</option><option>Harassment or abuse</option><option>Impersonation</option><option>Something else</option></select></label><button class="primary">Preview report</button></form>');break;case'job':{const j=jobs.find(j=>String(j.id)===id);modal(`<div class="eyebrow">SAMPLE OPPORTUNITY</div><h2>${j.title}</h2><p>${j.company} · ${j.location} · ${j.type}</p><p>${j.description}</p><p>${j.skills}</p><div class="notice">This is an example listing. No employer is receiving applications.</div><button class="primary" data-action="sampleapply">Preview application</button>`);break}case'sampleapply':modal('<h2>Your application preview</h2><p>A live application would share your profile with the opportunity owner, with your confirmation.</p><div class="notice">Nothing has been submitted.</div><a class="button primary" href="#profile" data-action="close">Review your profile</a>');break;case'postopportunity':modal('<h2>Post an opportunity</h2><p>Opportunity publishing opens after verified accounts are connected. Explore the sample listings to review the layout.</p>');break;case'group':{const g=groups.find(g=>g.id===id);modal(`<div class="eyebrow">SAMPLE COMMUNITY</div><h2>${g.name}</h2><p>${g.description}</p><div class="panel pad"><b>Welcome to the community</b><p>Introduce yourself, share what you’re working on, or ask for a useful connection.</p></div><button class="primary" data-action="joingroup" data-id="${g.id}">${state.joined.includes(g.id)?'Leave preview community':'Join preview community'}</button>`);break}case'joingroup':toggle('joined',id);closeModal();toast('Preview community preference updated.');break;case'rsvp':{const ev=events.find(e=>e.id===id);modal(`<div class="eyebrow">SAMPLE EVENT · OCTOBER 2026</div><h2>${ev.title}</h2><p>${ev.topic}</p><p>${ev.day} ${ev.month} · ${ev.time}</p><div class="notice">Concept event only. No real booking or reminder will be created.</div><button class="primary" data-action="eventsave" data-id="${id}">${state.rsvp.includes(id)?'Remove from preview events':'Save to preview events'}</button>`);break}case'eventsave':toggle('rsvp',id);closeModal();break;case'reset':modal('<h2>Clear preview data?</h2><p>This removes your sample posts, messages, follows and profile changes from this browser session.</p><button class="primary" data-action="confirmreset">Clear preview data</button>');break;case'confirmreset':sessionStorage.removeItem('virtlink-preview-v1');location.reload();break;}});
document.addEventListener('submit',e=>{const f=e.target;if(!['searchForm','postForm','networkFilter','profileForm','messageForm','commentForm','reportForm'].includes(f.id))return;e.preventDefault();const d=new FormData(f);switch(f.id){case'searchForm':searchQuery=$('#globalSearch').value.trim().slice(0,200);location.hash='search';render();break;case'postForm':{const text=String(d.get('post')).trim();if(!text)return;state.posts.unshift({id:'local-'+Date.now(),person:'me',time:'Just now',text,tags:[],likes:0});save();feedTab='all';render();toast('Preview post added. Visible only in this session.');break}case'networkFilter':searchQuery=String(d.get('q')).trim();networkFilter=String(d.get('field'));render();break;case'profileForm':{if(accountConnected){location.href='accounts.html';return;}const name=String(d.get('name')).trim();if(!name)return;state.profile={...state.profile,name,initials:name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(),role:String(d.get('role')).trim(),location:String(d.get('location')).trim(),skills:String(d.get('skills')).split(',').map(s=>s.trim()).filter(Boolean).slice(0,8),intent:String(d.get('intent')).trim(),bio:String(d.get('bio')).trim()};save();closeModal();render();toast('Preview profile updated.');break}case'messageForm':{const t=String(d.get('message')).trim();if(!t)return;(state.messages[selectedThread]??=[]).push(t);save();render();$('.chatBody').scrollTop=$('.chatBody').scrollHeight;break}case'commentForm':{const t=String(d.get('comment')).trim();if(!t)return;(state.comments[f.dataset.id]??=[]).push(t);save();closeModal();render();break}case'reportForm':closeModal();toast('Preview complete. No report has been submitted.');break;}});
document.addEventListener('change',e=>{if(e.target.id==='jobType'){jobFilter=e.target.value;render()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
render();

window.addEventListener('virtlink-account',event=>{
  const row=event.detail;if(accountId!==row?.user_id){pendingLikes.clear();commentsPostId=null;memberComments=[];commentDraft='';memberPosts=[];memberDraft='';memberLoaded=false;memberFeedError='';memberPosting=false;}accountId=row?.user_id??null;accountConnected=Boolean(row);
  state.profile=row?{id:'me',name:row.display_name,username:row.username,initials:row.display_name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(),avatar_data:row.avatar_data||'',role:row.headline||row.profession,location:row.location,field:row.profession,skills:row.skills.split(',').map(s=>s.trim()).filter(Boolean),intent:row.looking_for,bio:row.bio,color:''}:structuredClone(previewProfile);
  const login=document.querySelector('.loginButton');login.textContent=row?'Sign out':'Login';login.dataset.action=row?'signout':'signin';
  document.querySelector('.signupButton').hidden=Boolean(row);
  document.querySelector('.previewBar span').textContent=row?'PRIVATE MEMBER TEST · Real saved account data. Not a public launch.':'CONCEPT PREVIEW · Sample people and content. Actions stay in this browser session.';
  closeModal();render();
});
window.addEventListener('virtlink-account-error',()=>toast('Could not load your account. Open Login to check your session.'));

window.addEventListener('virtlink-feed',event=>{
  if(!accountConnected)return;const {rows,error}=event.detail;
  if(rows){memberPosts=rows;memberLoaded=true;}memberFeedError=error||'';
  if(['#feed','#profile','#profile/me'].includes(location.hash))render();
});
window.addEventListener('virtlink-post-status',event=>{
  if(!accountConnected)return;const {busy,saved,error}=event.detail;if(busy!==undefined)memberPosting=busy;
  if(saved){memberDraft='';toast('Post published to members.');}if(error)toast(error);
  if(location.hash==='#feed')render();
});
document.addEventListener('input',event=>{if(event.target.closest('#memberPostForm'))memberDraft=event.target.value;});
document.addEventListener('submit',event=>{
  if(event.target.id!=='memberPostForm')return;event.preventDefault();
  if(!accountConnected||memberPosting)return;
  const text=String(new FormData(event.target).get('post')).trim();if(!text){toast('Write something before publishing.');return;}
  window.dispatchEvent(new CustomEvent('virtlink-post-create',{detail:text}));
});

function renderComments(){
 if(!commentsPostId||!accountConnected)return;
 modal(`<h2>Member comments</h2><p>Comments and your name are visible to signed-in members.</p><small>Latest 100 comments</small>${commentsError?`<p class="notice" role="alert">${esc(commentsError)}</p>`:''}<div class="stack" style="margin:16px 0">${memberComments.map(c=>`<article class="panel pad"><div class="between"><b>${esc(c.author_name)}</b>${c.author_id===accountId?`<button class="textButton" data-action="deletecomment" data-id="${esc(c.id)}">Delete comment</button>`:''}</div><small>@${esc(c.author_username)} · ${esc(new Date(c.created_at).toLocaleString())}</small><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(c.body)}</p></article>`).join('')||`<p>${commentsLoading?'Loading comments…':'No comments yet.'}</p>`}</div><form id="memberCommentForm"><label>Your comment<textarea name="comment" required maxlength="1000" rows="3" ${commentSending?'disabled':''}>${esc(commentDraft)}</textarea></label><button class="primary" ${commentSending||commentsLoading?'disabled':''}>${commentSending?'Posting…':'Post comment'}</button></form>`);
}
$('#modal').addEventListener('close',()=>{commentsPostId=null;});
window.addEventListener('virtlink-like-done',event=>{pendingLikes.delete(event.detail);if(accountConnected&&['#feed','#profile','#profile/me'].includes(location.hash))render();});
window.addEventListener('virtlink-comments',event=>{
 const {postId,rows,saved,error,busy}=event.detail;if(postId!==commentsPostId||!accountConnected)return;
 if(rows){memberComments=rows;commentsLoading=false;commentsError='';}if(saved){commentDraft='';toast('Comment posted.');}
 if(error){commentsError=error;commentsLoading=false;}if(busy!==undefined)commentSending=busy;
 renderComments();
});
document.addEventListener('input',event=>{if(event.target.closest('#memberCommentForm'))commentDraft=event.target.value;});
document.addEventListener('submit',event=>{
 if(event.target.id!=='memberCommentForm')return;event.preventDefault();if(!commentsPostId||commentSending)return;
 const body=String(new FormData(event.target).get('comment')).trim();if(!body){toast('Write a comment first.');return;}
 commentSending=true;commentsError='';renderComments();window.dispatchEvent(new CustomEvent('virtlink-comment-create',{detail:{postId:commentsPostId,body}}));
});

window.addEventListener('message',event=>{
 if(event.origin!==location.origin||event.source!==document.querySelector('#profileEditorFrame')?.contentWindow)return;
 if(event.data?.type==='virtlink-profile-saved'){closeModal();window.dispatchEvent(new CustomEvent('virtlink-account-refresh'));toast('Profile updated.');}
 if(event.data?.type==='virtlink-profile-cancel')closeModal();
});

let memberPhotoProcessing=false,memberProfileSaving=false;
document.addEventListener('change',async event=>{
 if(event.target.id!=='memberPhoto')return;const file=event.target.files[0];if(!file)return;
 const form=document.querySelector('#memberProfileForm'),status=form.querySelector('#memberProfileStatus');memberPhotoProcessing=true;
 try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10485760)throw new Error('Choose a JPG, PNG or WebP under 10 MB.');
 const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.fillStyle='#fff';ctx.fillRect(0,0,256,256);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,256,256);bitmap.close();const photo=canvas.toDataURL('image/jpeg',.82);if(photo.length>100000)throw new Error('Choose a smaller picture.');form.avatarData=photo;const preview=form.querySelector('#memberPhotoPreview');preview.src=photo;preview.hidden=false;status.textContent='Photo ready.';
 }catch(error){status.textContent=error.message;}finally{memberPhotoProcessing=false;}
});
document.addEventListener('submit',event=>{
 if(event.target.id!=='memberProfileForm')return;event.preventDefault();if(memberProfileSaving)return;
 const form=event.target,status=form.querySelector('#memberProfileStatus');if(memberPhotoProcessing){status.textContent='Wait for your picture to load.';return;}
 memberProfileSaving=true;form.querySelector('button[type="submit"],button.primary').disabled=true;status.textContent='Saving…';
 window.dispatchEvent(new CustomEvent('virtlink-profile-save',{detail:{...Object.fromEntries(new FormData(form)),avatar_data:form.avatarData??state.profile.avatar_data??''}}));
});
window.addEventListener('virtlink-profile-result',event=>{memberProfileSaving=false;const form=document.querySelector('#memberProfileForm');if(event.detail.error&&form){form.querySelector('button.primary').disabled=false;form.querySelector('#memberProfileStatus').textContent=event.detail.error;}else if(event.detail.saved){closeModal();toast('Profile updated.');}});
